"""Deterministic plugin icon bytes generated by this file; no artwork is copied from any source.

PNG fixtures are CRC-correct; IDAT holds a fixed stored-block zlib stream so bytes are identical in any language. WebP fixtures are static
VP8L headers whose bitstream after the 5-byte header is a dummy, because the contract is structural only.
`python3 tests/icon_fixtures.py` regenerates tests/fixtures/plugin-icons.json.
"""
import base64
import json
import struct
import zlib
from pathlib import Path

VECTORS_PATH = Path(__file__).resolve().parent / 'fixtures' / 'plugin-icons.json'


def _chunk(kind, body):
    return struct.pack('>I', len(body)) + kind + body + struct.pack('>I', zlib.crc32(kind + body))


def _stored(raw):
    out, rest = b'\x78\x01', raw
    while True:
        block, rest = rest[:65535], rest[65535:]
        out += bytes([0 if rest else 1]) + struct.pack('<HH', len(block), len(block) ^ 0xFFFF) + block
        if not rest:
            return out + struct.pack('>I', zlib.adler32(raw))


def png(width=1, height=1, bad_crc=False, pad=0):
    ihdr = struct.pack('>IIBBBBB', width, height, 8, 6, 0, 0, 0)
    idat = _stored(b'\x00' + bytes(4))  # structural contract: pixels are never decoded, so one dummy row suffices
    chunks = [_chunk(b'IHDR', ihdr), _chunk(b'IDAT', idat)]
    if pad:
        chunks.append(_chunk(b'tEXt', b'k\x00' + b'x' * pad))
    chunks.append(_chunk(b'IEND', b''))
    data = b'\x89PNG\r\n\x1a\n' + b''.join(chunks)
    if bad_crc:
        data = data[:29] + bytes([data[29] ^ 1]) + data[30:]  # IHDR CRC byte
    return data


def webp(width=1, height=1, animated=False):
    lossless = b'\x2f' + struct.pack('<I', (width - 1) | ((height - 1) << 14))
    payload = b'WEBP'
    if animated:
        payload += b'VP8X' + struct.pack('<I', 10) + bytes([0x02, 0, 0, 0]) \
            + (width - 1).to_bytes(3, 'little') + (height - 1).to_bytes(3, 'little')
    payload += b'VP8L' + struct.pack('<I', len(lossless)) + lossless + b'\x00' * (len(lossless) % 2)
    return b'RIFF' + struct.pack('<I', len(payload)) + payload


def b64(data):
    return base64.b64encode(data).decode('ascii')


def vectors():
    cases = [
        ('png-1x1', 'png', 'icon.png', png(), True, 1, 1),
        ('png-1024x1024', 'png', 'icon.png', png(1024, 1024), True, 1024, 1024),
        ('webp-1x1', 'webp', 'icon.webp', webp(), True, 1, 1),
        ('webp-1024x1024', 'webp', 'icon.webp', webp(1024, 1024), True, 1024, 1024),
        ('png-width-1025', 'png', 'icon.png', png(1025, 1), False, 1025, 1),
        ('png-bad-crc', 'png', 'icon.png', png(bad_crc=True), False, 1, 1),
        ('png-truncated', 'png', 'icon.png', png()[:-4], False, 1, 1),
        ('webp-height-1025', 'webp', 'icon.webp', webp(1, 1025), False, 1, 1025),
        ('webp-animated', 'webp', 'icon.webp', webp(animated=True), False, 1, 1),
        ('webp-wrong-magic', 'webp', 'icon.webp', b'RIFX' + webp()[4:], False, 1, 1),
    ]
    return [{'name': n, 'format': f, 'path': p, 'base64': b64(d), 'expectedValid': ok,
             'width': w, 'height': h} for n, f, p, d, ok, w, h in cases]


if __name__ == '__main__':
    VECTORS_PATH.write_text(json.dumps(vectors(), indent=1) + '\n')
